mapper.select:
select ra.* ,oi.product_price as productRealPrice,oi.product_quantity as productCount
from return_apply ra
left join order_item oi on ra.order_id = oi.order_sn


        and ra.id = #{id}


        and ra.status = #{status}


        and ra.handle_man = #{handleMan}


        and ra.return_name = #{returnName}


        and ra.handle_time <= #{endTime}


        and ra.handle_time >= #{startTime}


        and ra.create_time <= #{endTime}


        and ra.create_time >= #{startTime}


        and ra.handle_time <= #{endTime1}


        and ra.handle_time >= #{startTime1}


order by  create_time desc
